fn unit(d: Int) -> Float {
    var f = 0.0
    var i = 0
    while i < d {
        f = f + 1.0
        i = i + 1
    }
    return f
}

fn pos_float(n: Int) -> Float {
    if n < 10 {
        return unit(n)
    }
    return pos_float(n / 10) * 10.0 + unit(n - (n / 10) * 10)
}

fn to_float(n: Int) -> Float {
    if n < 0 {
        return 0.0 - pos_float(0 - n)
    }
    return pos_float(n)
}

fn insert_int(xs: List[Int], x: Int) -> List[Int] {
    var out: List[Int] = []
    var placed = false
    for y in xs {
        if not placed and y > x {
            out = out.push(x)
            placed = true
        }
        out = out.push(y)
    }
    if not placed {
        out = out.push(x)
    }
    return out
}

pub fn medians(xs: List[Int], k: Int) -> List[Float] {
    var out: List[Float] = []
    let n = xs.len()
    if k < 1 or k > n {
        return out
    }
    var s = 0
    while s + k <= n {
        var sorted: List[Int] = []
        var j = 0
        while j < k {
            sorted = insert_int(xs: sorted, x: at(xs, s + j))
            j = j + 1
        }
        let half = k / 2
        var med = 0.0
        if (k / 2) * 2 == k {
            med = (to_float(at(sorted, half - 1)) + to_float(at(sorted, half))) / 2.0
        } else {
            med = to_float(at(sorted, half))
        }
        out = out.push(med)
        s = s + 1
    }
    return out
}
